mapper.select:
SELECT * FROM workitem_duplicate_check
WHERE tenant_id = #{tenantId} AND id = #{id}
LIMIT 1

SELECT * FROM workitem_duplicate_check
WHERE tenant_id = #{tenantId} AND operator_id = #{operatorId}
  AND form_request_id = #{formRequestId} AND title_fingerprint = #{titleFingerprint}
ORDER BY id DESC
LIMIT 1

SELECT enabled FROM platform_feature_switch
WHERE switch_key = #{switchKey}
FOR UPDATE

SELECT id FROM workitem_duplicate_check
WHERE status IN ('PENDING', 'RUNNING')
  AND deadline_at IS NOT NULL AND deadline_at <= #{now}
ORDER BY id ASC
LIMIT #{limit}

mapper.update:
UPDATE workitem_duplicate_check
SET status = 'RUNNING', lease_until = #{leaseUntil}, attempt = attempt + 1
WHERE id = #{id}
  AND attempt = #{expectedAttempt}
  AND (status = 'PENDING'
       OR (status = 'RUNNING' AND (lease_until IS NULL OR lease_until <= #{now})))

UPDATE workitem_duplicate_check
SET status = 'CANCELED', lease_until = NULL, cancel_pending = 0
WHERE tenant_id = #{tenantId} AND operator_id = #{operatorId}
  AND form_request_id = #{formRequestId} AND id <> #{exceptId}
  AND status IN ('PENDING', 'RUNNING')

mapper.select:
SELECT id FROM workitem_duplicate_check
WHERE workitem_id IS NULL AND status IN ('SUCCEEDED', 'FAILED', 'CANCELED', 'SKIPPED')
  AND gmt_create < #{before}
ORDER BY id ASC
LIMIT #{limit}

SELECT COUNT(1)
FROM agent_conversation c
WHERE c.id = #{conversationId}
  AND c.tenant_id = #{tenantId}
  AND c.channel = 'PLATFORM_INTERNAL'
  AND EXISTS (
      SELECT 1 FROM workitem_duplicate_check d
      WHERE d.tenant_id = c.tenant_id
        AND d.request_id = c.channel_conversation_id
  )
